#!/usr/bin/env bash
set -euo pipefail
export PYTHONDONTWRITEBYTECODE=1
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B -I - <<'SHARED_RELEASE_BOOTSTRAP'
ROOT='/data1/home/sunyiq/zhenjiang_shared_base_20260916_001'
CORE_REL='runtime/inbox/zhenjiang-six-source-four-target-ukf/shared_base_20260916_001'
RELEASE_SHA='49a27c4d9ea0f4f1843d581c780adfa554e8dc4498623cdc2c277aed3aa7856a'
PAYLOAD=''

import base64,hashlib,json,os,stat,sys,runpy,zlib
from pathlib import Path
root=Path(ROOT)
if str(root)!="/data1/home/sunyiq/zhenjiang_shared_base_20260916_001":
    raise ValueError("unexpected exclusive root")
payload=json.loads(zlib.decompress(base64.b64decode(PAYLOAD,validate=True)))
manifest_raw=base64.b64decode(payload["manifest"],validate=True)
if hashlib.sha256(manifest_raw).hexdigest()!=RELEASE_SHA:
    raise ValueError("manifest identity differs")
manifest=json.loads(manifest_raw)
if manifest["remote_root"]!=str(root):
    raise ValueError("manifest root differs")
files={name:base64.b64decode(raw,validate=True) for name,raw in payload["files"].items()}
rows=manifest["files"]
if len(rows)!=len(files) or len(files)>60 or set(files)!={r["path"] for r in rows}:
    raise ValueError("bundle member allowlist differs")
for row in rows:
    name=row["path"]
    if name.startswith("/") or "\\" in name or ":" in name or any(p in ("",".","..") for p in name.split("/")):
        raise ValueError("invalid source member")
    raw=files[name]
    if not (name.endswith(".py") or name.endswith(".json")) or len(raw)!=row["bytes"] or hashlib.sha256(raw).hexdigest()!=row["sha256"]:
        raise ValueError("source identity differs")
for path in (root,*root.parents):
    try: meta=path.lstat()
    except FileNotFoundError: continue
    if stat.S_ISLNK(meta.st_mode):
        raise ValueError("linked deployment path")
os.umask(0o077)
flags=os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW
parent_fd=os.open("/",flags)
for part in root.parent.parts[1:]:
    child=os.open(part,flags,dir_fd=parent_fd)
    os.close(parent_fd);parent_fd=child
parent_meta=os.fstat(parent_fd)
os.mkdir(root.name,0o700,dir_fd=parent_fd)
root_fd=os.open(root.name,flags,dir_fd=parent_fd)
root_meta=os.fstat(root_fd)
def check_root():
    for path in (root,*root.parents):
        if stat.S_ISLNK(path.lstat().st_mode):
            raise ValueError("deployment path became linked")
    visible=root.stat()
    parent_visible=root.parent.stat()
    if (visible.st_dev,visible.st_ino)!=(root_meta.st_dev,root_meta.st_ino) or (parent_visible.st_dev,parent_visible.st_ino)!=(parent_meta.st_dev,parent_meta.st_ino):
        raise ValueError("exclusive directory identity changed")
def put(name,raw):
    check_root()
    fd=os.dup(root_fd)
    try:
        parts=name.split("/")
        for part in parts[:-1]:
            try: os.mkdir(part,0o700,dir_fd=fd)
            except FileExistsError: pass
            child=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd)
            os.close(fd);fd=child
        out=os.open(parts[-1],os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600,dir_fd=fd)
        with os.fdopen(out,"wb") as handle:
            handle.write(raw);handle.flush();os.fsync(handle.fileno())
    finally: os.close(fd)
    check_root()
def verify_disk(name,expected):
    check_root()
    fd=os.dup(root_fd)
    try:
        parts=name.split("/")
        for part in parts[:-1]:
            child=os.open(part,flags,dir_fd=fd)
            os.close(fd);fd=child
        source=os.open(parts[-1],os.O_RDONLY|os.O_NOFOLLOW,dir_fd=fd)
        with os.fdopen(source,"rb",buffering=0) as handle:
            meta=os.fstat(handle.fileno())
            if not stat.S_ISREG(meta.st_mode) or meta.st_nlink!=1 or meta.st_size!=len(expected):
                raise ValueError("deployed source type/length differs")
            raw=b""
            while len(raw)<len(expected):
                chunk=handle.read(len(expected)-len(raw))
                if not chunk: break
                raw+=chunk
            if raw!=expected:
                raise ValueError("deployed source bytes differ")
    finally: os.close(fd)
    check_root()
try:
    for name,raw in files.items(): put(name,raw)
    put("release_manifest.json",manifest_raw)
    meta={"release_sha256":RELEASE_SHA,"root_identity":[root_meta.st_dev,root_meta.st_ino]}
    put("deployment.json",json.dumps(meta,sort_keys=True,separators=(",",":")).encode())
    for name,raw in files.items(): verify_disk(name,raw)
    verify_disk("release_manifest.json",manifest_raw)
    check_root()
finally:
    os.close(root_fd);os.close(parent_fd)
for location in (root/"execution",root/CORE_REL,root/"scripts/modeling",root/"scripts/astronomical_tide"):
    sys.path.insert(0,str(location))
sys.argv=["remote_actions.py","--action","submit","--stage","preflight","--release-sha",RELEASE_SHA]
check_root()
runpy.run_path(str(root/"execution/remote_actions.py"),run_name="__main__")

SHARED_RELEASE_BOOTSTRAP
